from typing import List

def specialPerm(nums: List[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7
    # Precompute adjacency matrix for divisibility
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                adj[i][j] = adj[j][i] = True

    # dp[mask][last_idx] is the number of permutations using bits in mask ending at last_idx
    dp = [[0] * n for _ in range(1 << n)]

    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(1, 1 << n):
        for i in range(n):
            if dp[mask][i] == 0:
                continue
            for j in range(n):
                if not (mask & (1 << j)) and adj[i][j]:
                    dp[mask | (1 << j)][j] = (dp[mask | (1 << j)][j] + dp[mask][i]) % MOD

    return sum(dp[(1 << n) - 1]) % MOD
